import type { Column, Typed } from '../Column'
import type { Record } from '../Record'
import type { TableNameColumnType } from './TableName'

type DocumentIdColumnType<
    Type extends Record | string = Record | string, // Allowing strings to be assigned is an escape hatch
    Default extends Type = Type,
> = Column<Type, Default> &
    (
        | {
              /**
               * @deprecated Pass the field name as a string instead
               *
               * Field name of a TableNameColumn within the same table schema.
               * This specifies which table this document ID references.
               */
              dependent?: TableNameColumnType
          }
        | {
              /**
               * Field name of a TableNameColumn within the same table schema.
               * This specifies which table this document ID references.
               */
              dependent: string
          }
    )

// TODO: Figure out how to properly constrain values for this
/**
 * A Column for a document ID type field.
 * References a record in a dynamically determined table.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **dependent**? - field name (string) of the TableNameColumn in the same schema
 *
 * @example
 * ```typescript
 * Table({
 *     name: 'my_table',
 *     schema: {
 *         source_table: TableNameColumn({ label: 'Source Table' }),
 *         source_record: DocumentIdColumn({
 *             label: 'Source Record',
 *             dependent: 'source_table', // References the field name
 *         }),
 *     },
 * })
 * ```
 */
export function DocumentIdColumn<
    const Type extends Record | string,
    const Default extends Type,
    const C extends DocumentIdColumnType<Type, Default>,
>(config: C & DocumentIdColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
